 const backup=await host.exportData(id);await host.uninstall(id,true);assert((await storage.list(id)).length===0,'Uninstall failed data deletion');await storage.restoreNamespace(id,backup,52428800);assert(await storage.get(id,'document')==='before','Export recovery failed');await host.install(old,['cache']);
 await storage.putJournal('active',{stage:'staging'});const lease=await storage.acquireLease('install/active','other');await host.recover();assert(await storage.getJournal('active'),'Recovery deleted another tab staging journal');await storage.releaseLease('install/active','other',lease.fence);await host.recover();assert(await storage.getJournal('active')===undefined,'Expired journal recovery failed');
